        blocks.markup = this.parseMarkupBlock();
      } else {
        throw new Error(`Unexpected block type: ${blockType} at line ${this.peek().line}`);
      }
    }

    this.expect('RBRACE');

    return {
      type: 'component',
      name,
      props: blocks.props || { properties: [] },
      style: blocks.style || { content: '' },
      script: blocks.script || { functions: [] },
      markup: blocks.markup || { content: '' }
    };
  }

  parsePropsBlock() {
    this.expect('PROPS');
    this.expect('LBRACE');

    const properties = [];
    while (this.peek() && this.peek().type !== 'RBRACE') {
      if (this.peek().type === 'IDENTIFIER') {
        const nameToken = this.expect('IDENTIFIER');
        this.expect('COLON');
        const typeToken = this.expect('IDENTIFIER');

        // 제네릭 타입 처리 (예: array<string>)
        let type = typeToken.value;
        if (this.peek() && this.peek().type === 'LT') {
          this.advance(); // <
          const innerType = this.expect('IDENTIFIER');
          this.expect('GT');
          type = `${type}<${innerType.value}>`;
        }

        properties.push({
          name: nameToken.value,
          type: type
        });
      }

      if (this.peek() && this.peek().type === 'COMMA') {
        this.advance();
      }
    }

    this.expect('RBRACE');

    return {
      type: 'props',
      properties
    };
  }

  parseStyleBlock() {
    this.expect('STYLE');
    this.expect('LBRACE');

    let content = '';
    let braceCount = 1;

    while (braceCount > 0 && this.peek()) {
      const token = this.peek();

      if (token.type === 'LBRACE') {
        braceCount++;
        content += token.value;
      } else if (token.type === 'RBRACE') {
        braceCount--;
        if (braceCount > 0) {
          content += token.value;
        }
      } else if (token.type === 'STRING') {
        content += `"${token.value}"`;
      } else if (token.type === 'NUMBER') {
        content += token.value;
      } else {
        content += token.value;
      }

      this.advance();
    }

    return {
      type: 'style',
      content: content.trim()
    };
  }

  parseScriptBlock() {
    this.expect('SCRIPT');
    this.expect('LBRACE');

    const functions = [];
    let content = '';
    let braceCount = 1;

    while (braceCount > 0 && this.peek()) {
      const token = this.peek();

      if (token.type === 'FN') {
        // 함수 정의 파싱
        this.advance(); // fn
        const fnName = this.expect('IDENTIFIER').value;
        this.expect('LPAREN');

        const params = [];
        while (this.peek() && this.peek().type !== 'RPAREN') {
          const param = this.expect('IDENTIFIER').value;
          params.push(param);

          if (this.peek().type === 'COMMA') {
            this.advance();
          }
        }

        this.expect('RPAREN');
        this.expect('LBRACE');

        let fnBody = '';
        let fnBraceCount = 1;

        while (fnBraceCount > 0 && this.peek()) {
          const tk = this.peek();

          if (tk.type === 'LBRACE') {
            fnBraceCount++;
            fnBody += tk.value;
          } else if (tk.type === 'RBRACE') {
            fnBraceCount--;
            if (fnBraceCount > 0) {
              fnBody += tk.value;
            }
          } else if (tk.type === 'STRING') {
            fnBody += `"${tk.value}"`;
          } else if (tk.type === 'NUMBER') {
            fnBody += tk.value;
          } else {
            fnBody += tk.value;
          }

          this.advance();
        }

        functions.push({
          name: fnName,
          params,
          body: fnBody.trim()
        });

        braceCount--; // script 블록 닫음
      } else if (token.type === 'LBRACE') {
        braceCount++;
        content += token.value;
        this.advance();
      } else if (token.type === 'RBRACE') {
        braceCount--;
        if (braceCount > 0) {
          content += token.value;
        }
        this.advance();
      } else {
        content += token.value;
        this.advance();
      }
    }

    return {
      type: 'script',
      functions,
      rawContent: content.trim()
    };
  }

  parseMarkupBlock() {
    this.expect('MARKUP');
    this.expect('LBRACE');

    let content = '';
    let braceCount = 1;

    while (braceCount > 0 && this.peek()) {
      const token = this.peek();

      if (token.type === 'LBRACE') {
        braceCount++;
        content += token.value;
      } else if (token.type === 'RBRACE') {
        braceCount--;
        if (braceCount > 0) {
          content += token.value;
        }
      } else if (token.type === 'STRING') {
        content += `"${token.value}"`;
      } else if (token.type === 'NUMBER') {
        content += token.value;
      } else {
        content += token.value;
      }

      this.advance();
    }

    return {
      type: 'markup',
      content: content.trim()
    };
  }
}

function parseFreeLang(source) {
  const tokenizer = new Tokenizer(source);
  const tokens = tokenizer.tokenize();

  const parser = new Parser(tokens);
  const ast = parser.parseComponent();

  return ast;
}

module.exports = { parseFreeLang, Tokenizer, Parser };

