    28→
    29→// 간단한 메모리 캐시
    30→const memCache = new Map();
    31→
    32→// ✅ 1️⃣ 리스트 조회 API (Pagination + Filtering + Caching + Selective Fields)
    33→app.get('/api/v1/packages', (req, res) => {
    34→  try {
    35→    const { limit = 10, offset = 0, sort = 'id', filter, fields = 'id,name,url,description' } = req.query;
    36→    const cacheKey = `packages:${limit}:${offset}:${sort}:${filter}:${fields}`;
