        }
        this.searchComponents(cmdArgs.join(' '));
        break;

      case 'index':
        if (!cmdArgs[0]) {
          console.error('❌ Usage: freelang index <directory>');
          process.exit(1);
        }
        this.indexDirectory(cmdArgs[0]);
        break;

      case 'list':
        this.listComponents();
        break;

      case 'stats':
        this.showStats();
        break;

      case 'serve':
        this.startServer();
        break;

      case 'help':
      case '-h':
      case '--help':
        this.showHelp();
        break;

      case 'version':
      case '-v':
      case '--version':
        this.showVersion();
        break;

      default:
        console.error(`❌ Unknown command: ${command}`);
        console.log(`\nRun 'freelang help' for usage information.\n`);
        process.exit(1);
    }
  }
}

// CLI 실행
if (require.main === module) {
  const cli = new FreeLangCLI();
  cli.run(process.argv.slice(2));
}

module.exports = { FreeLangCLI };

