 */
bundleComponents(dirPath, args = []) {
  console.log(`\n📦 Bundling components from: ${dirPath}`);

  if (!fs.existsSync(dirPath)) {
    console.error(`❌ Directory not found: ${dirPath}`);
    process.exit(1);
  }

  try {
    const options = {
      minify: !args.includes('--no-minify'),
      sourcemap: args.includes('--sourcemap'),
      bundleName: 'app'
    };

    const bundler = new Bundler(options);

    // 디렉토리의 모든 .css, .js, .html 파일 찾기
    const files = this.findComponentAssets(dirPath);

    if (files.length === 0) {
      console.error(`❌ No component assets found in ${dirPath}`);
      process.exit(1);
    }

    console.log(`\n📄 Found ${files.length} assets\n`);

    files.forEach(file => {
      bundler.bundleComponent(file);
    });

    const result = bundler.generate();

    console.log(`\n📊 Bundle Summary:`);
    console.log(`   Output: ${result.css}`);
    console.log(`   Size: ${result.stats.total_size_uncompressed} bytes`);
    console.log();
  } catch (error) {
    console.error(`❌ Bundling failed: ${error.message}`);
    process.exit(1);
  }
}

/**
 * 컴포넌트 자산 찾기
 */
findComponentAssets(dirPath) {
  const files = [];
  const extensions = ['.css', '.js', '.html'];

  const traverse = (currentPath) => {
    const entries = fs.readdirSync(currentPath, { withFileTypes: true });

    entries.forEach(entry => {
      const fullPath = path.join(currentPath, entry.name);

      if (entry.isDirectory() && !entry.name.startsWith('.')) {
        traverse(fullPath);
      } else if (entry.isFile() && extensions.includes(path.extname(entry.name))) {
        files.push(fullPath);
      }
    });
  };

  traverse(dirPath);
  return files;
}

/**
 * serve 명령
 */
startServer() {
  const api = new FreeLangSearchAPI();
  api.startServer();
}

