        this.bundleComponents(cmdArgs[0], cmdArgs);
        break;

      case 'serve':
        this.startServer();
        break;

      case 'help':
      case '-h':
      case '--help':
        this.showHelp();
        break;

      case 'version':
      case '-v':
      case '--version':
        this.showVersion();
        break;

      default:
        console.error(`❌ Unknown command: ${command}`);
        console.log(`\nRun 'freelang help' for usage information.\n`);
        process.exit(1);
    }
  }
}

// CLI 실행
if (require.main === module) {
  const cli = new FreeLangCLI();
  cli.run(process.argv.slice(2));
}

module.exports = { FreeLangCLI };

